function failedColumns(row:FailedRecord){const keys=Object.keys(row.record||{});const reason=(row.failure_reasons||[]).join(' ').toLowerCase();const matches=keys.filter(key=>reason.includes(key.toLowerCase()));return matches.length?matches:keys}
async function finishFix(){if(!runId){Serror('Run validation before saving a correction.');return}if(!fix.column_name){Serror('Choose a column to correct.');return}Serror('');Snotice('');try{await api(`/executions/${runId}/corrections`,{method:'POST',...json({row_index:fix.row_index,column_name:fix.column_name,value:fix.value})});Sfailed(rows=>rows.map(row=>row.row_index===fix.row_index?{...row,record:{...row.record,[fix.column_name]:fix.value}}:row));Snotice('Correction saved. Revalidate to update the result.');}catch(e){Serror(e instanceof Error?e.message:'Could not save correction')}}
async function revalidateCorrections(){if(!runId)return;Sloading(true);Serror('');Snotice('');try{const sourceRows=failed;const result=await api<{revalidated:number;passed:number;failed:number}>(`/executions/${runId}/revalidate`,{method:'POST'});const updatedRows=await api<FailedRecord[]>(`/executions/${runId}/artifacts/revalidated_failed.json`);const rows=updatedRows.map(row=>({...row,row_index:sourceRows[row.row_index]?.row_index??row.row_index}));Sfailed(rows);Sruns(v=>({...v,[activeJob||0]:[{...(v[activeJob||0]?.[0]||{id:runId,status:'succeeded',finished_at:null}),id:runId,passed_count:result.passed,failed_count:result.failed},...(v[activeJob||0]||[]).filter(item=>item.id!==runId)]}));if(rows.length)selectFailedRecord(rows[0]);else Sfix({row_index:0,column_name:'',value:''});Snotice(`Revalidation complete: ${result.passed} passed, ${result.failed} failed.`)}catch(e){Serror(e instanceof Error?e.message:'Could not revalidate corrections')}finally{Sloading(false)}}
 function beginWorkflow(){const next=crypto.randomUUID();Sname('');Sdesc('');Sjob(null);Sselected([]);Sds([]);Scolumns({});SsourceConnections({});Sworkflow(next);Sstage(2);SshowJobForm(true);persist({stage:2,activeJob:null,datasetIds:[],columns:{},sourceConnections:{},workflowId:next})}
